import{_ as a,a as e,b as t}from"./chunks/m_filtrace.DRtLeEEZ.js";import{_ as l}from"./chunks/img_2326-portrait_1.DGqQCP4f.js";import{_ as i,a as r,b as n,c as s}from"./chunks/m_prilohy_menu.BEI7bXma.js";import{_ as k,o as p,c as u,aa as v}from"./chunks/framework.BAs_AphD.js";const w=JSON.parse('{"title":"Úkoly v mobilu","description":"","frontmatter":{"title":"Úkoly v mobilu","wiki":"cs:tickets:m_task_grid"},"headers":[],"relativePath":"tickets/m_task_grid.md","filePath":"tickets/m_task_grid.md","lastUpdated":1794209661000}'),d={name:"tickets/m_task_grid.md"};function m(h,o,y,g,c,b){return p(),u("div",null,[...o[0]||(o[0]=[v('<h1 id="ukoly-v-mobilu" tabindex="-1">Úkoly v mobilu <a class="header-anchor" href="#ukoly-v-mobilu" aria-label="Permalink to &quot;Úkoly v mobilu&quot;">​</a></h1><p>V mobilní aplikaci máte úkoly stavby po ruce přímo na místě: najdete je v seznamu nebo na výkresu, změníte stav, odpovíte vyjádřením a přiložíte fotky. Tato stránka popisuje, co je na telefonu jinak než na webu.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/editace-ukolu">Změnit stav úkolu a odpovědět</a> v Akademii.</p><h2 id="seznam-ukolu" tabindex="-1">Seznam úkolů <a class="header-anchor" href="#seznam-ukolu" aria-label="Permalink to &quot;Seznam úkolů&quot;">​</a></h2><p>Seznam otevřete v menu aplikace volbou <strong>Management úkolů</strong> → <strong>Seznam úkolů</strong> (viz <a href="/buildary-help-preview/diary/m_project_list">Seznam staveb a menu v mobilu</a>), nebo v deníku ikonou úkolů vpravo v záhlaví. Ukazuje úkoly stavby, ve které právě jste. Ikonou deníku vpravo v záhlaví přejdete do stavebního deníku téže stavby.</p><div class="shots"><figure class="shot" style="--w:260px;"><img src="'+a+'" alt="Seznam úkolů v mobilu: karty úkolů s číslem, stavem, prioritou, přílohami a podrobnostmi" loading="lazy"></figure><figure class="shot" style="--w:260px;"><img src="'+e+'" alt="Karta úkolu s rozbalenými podrobnostmi" loading="lazy"></figure></div><p>Každý úkol má v seznamu kartu:</p><ul><li>nahoře číslo úkolu, stav a prioritu; ikona vpravo nahoře znamená, že úkol má vyjádření,</li><li>uprostřed předmět úkolu – klepnutím úkol otevřete,</li><li>dole počet příloh a tlačítko <strong>Podrobnosti</strong>, které rozbalí základní údaje o úkolu.</li></ul><p>Tlačítky vpravo dole zakládáte nové úkoly: <strong>+</strong> otevře prázdný formulář, ikona fotoaparátu začne fotkou. Viz <a href="/buildary-help-preview/tickets/m_task_new">Nový úkol v mobilu</a>.</p><p>Které úkoly v seznamu vidíte, určují vaše oprávnění na stavbě – viz <a href="/buildary-help-preview/tickets/permissions">Kdo co smí v úkolech</a>.</p><h2 id="filtrovat-a-radit-ukoly" tabindex="-1">Filtrovat a řadit úkoly <a class="header-anchor" href="#filtrovat-a-radit-ukoly" aria-label="Permalink to &quot;Filtrovat a řadit úkoly&quot;">​</a></h2><p>Klepněte na řádek <strong>Filtrace</strong> nad seznamem. Filtry můžete libovolně kombinovat.</p><figure class="shot" style="--w:260px;"><img src="'+t+'" alt="Rozbalená Filtrace: hledání, kalendář, Vztah k úkolu, Aktuálnost úkolu a filtry podle kategorie, štítků, stavu a dalších údajů" loading="lazy"></figure><ul><li><strong>Hledání</strong> (lupa) – najde úkoly, které mají hledané slovo v předmětu nebo popisu. Slovo stačí zadat v základním tvaru, vyhledávání si poradí se skloňováním.</li><li><strong>Kalendář</strong> – omezí úkoly podle data plánovaného a skutečného začátku a konce.</li><li><strong>Vztah k úkolu</strong> a <strong>Aktuálnost úkolu</strong> – z každého vyberte jednu možnost.</li><li><strong>Kategorie</strong>, <strong>Štítky</strong>, <strong>Stav</strong>, <strong>Priorita</strong>, <strong>Část stavby</strong>, <strong>Řešitelé</strong>, <strong>Schvalovatelé</strong>, <strong>Autor</strong>, <strong>Firmy řešitelů</strong> – klepnutím na řádek nebo ikonu trychtýře vyberete jednu nebo více hodnot.</li></ul><p>Ikonou na konci řádku seznam podle daného údaje seřadíte: první klepnutí řadí vzestupně, druhé sestupně, třetí řazení vypne.</p><p>Co jednotlivé filtry znamenají, popisuje <a href="/buildary-help-preview/tickets/task_grid">Seznam úkolů a filtry</a>.</p><h2 id="ukoly-na-vykresu-a-v-mape" tabindex="-1">Úkoly na výkresu a v mapě <a class="header-anchor" href="#ukoly-na-vykresu-a-v-mape" aria-label="Permalink to &quot;Úkoly na výkresu a v mapě&quot;">​</a></h2><p>V menu aplikace zvolte <strong>Management úkolů</strong> → <strong>Výkresy a mapa</strong>. Úkoly umístěné na výkresu nebo v mapě uvidíte jako očíslované značky. Klepnutím na značku zobrazíte kartu úkolu; tlačítkem <strong>Podrobnosti</strong> úkol otevřete.</p><figure class="shot" style="--w:260px;"><img src="'+l+'" alt="Výkres v mobilu s očíslovanými značkami úkolů a kartou vybraného úkolu" loading="lazy"></figure><p>Odtud můžete úkol i založit – viz <a href="/buildary-help-preview/tickets/m_task_new">Nový úkol v mobilu</a>. Jak výkresy a mapa fungují, popisuje <a href="/buildary-help-preview/tickets/task_drawings">Výkresy a mapa</a>.</p><h2 id="otevrit-a-upravit-ukol" tabindex="-1">Otevřít a upravit úkol <a class="header-anchor" href="#otevrit-a-upravit-ukol" aria-label="Permalink to &quot;Otevřít a upravit úkol&quot;">​</a></h2><p>Klepněte v seznamu na předmět úkolu. Úkol se otevře ve stejném formuláři, ve kterém se zakládá. Pod předmětem jsou čtyři záložky – základní údaje, přílohy, výkresy a mapa, účastníci; číslo u záložky ukazuje počet položek.</p><figure class="shot" style="--w:260px;"><img src="'+i+'" alt="Otevřený úkol v mobilu: předmět, záložky, popis, kategorie, stav, priorita, štítky a termíny" loading="lazy"></figure><p><strong>Změnit stav</strong> – klepněte na pole <strong>Stav</strong> a vyberte nový stav. Změny uložte modrým tlačítkem s fajfkou vpravo dole. Co jednotlivé stavy znamenají a jak úkol prochází řešením a schválením, popisuje <a href="/buildary-help-preview/tickets/task_edit#stavy-ukolu">Řešit a schválit úkol</a>.</p><p>Upravit můžete jen to, co vám dovolí váš vztah k úkolu (Zadavatel, Řešitel, Schvalovatel) a vaše role v projektovém týmu – viz <a href="/buildary-help-preview/tickets/permissions">Kdo co smí v úkolech</a>. Skutečný začátek a konec úkolu doplňuje aplikace sama, ručně je změnit nejde.</p><h2 id="vyjadreni" tabindex="-1">Vyjádření <a class="header-anchor" href="#vyjadreni" aria-label="Permalink to &quot;Vyjádření&quot;">​</a></h2><p>Vyjádření jsou oficiální zápisy k řešení úkolu – viz <a href="/buildary-help-preview/tickets/task_edit#vyjadreni">Řešit a schválit úkol</a>. V mobilu je otevřete ikonou bubliny v dolní liště úkolu. Oranžová tečka u ikony znamená, že úkol už nějaké vyjádření má.</p><div class="shots"><figure class="shot" style="--w:260px;"><img src="'+r+'" alt="Vyjádření k úkolu s připojenými fotkami" loading="lazy"></figure><figure class="shot" style="--w:260px;"><img src="'+n+'" alt="Obrazovka Vyjádření s ikonami odpovědi u příspěvků a dolní lištou s fotoaparátem, galerií, přílohou a tlačítkem +" loading="lazy"></figure></div><ul><li><strong>Nové vyjádření</strong> – klepněte na <strong>+</strong> v dolní liště.</li><li><strong>Odpověď</strong> – klepněte na ikonu šipky vpravo dole u příspěvku. Odpověď se zařadí pod něj.</li><li><strong>Přílohy</strong> – k vyjádření přiložíte fotku z fotoaparátu, obrázek z galerie nebo soubor z telefonu ikonami v dolní liště.</li></ul><p>Do vyjádření píší účastníci úkolu. Svůj příspěvek můžete upravit nebo smazat, dokud na něj nikdo neodpoví – viz <a href="/buildary-help-preview/tickets/permissions#vyjadreni-a-prilohy">Kdo co smí v úkolech</a>.</p><h2 id="prilohy" tabindex="-1">Přílohy <a class="header-anchor" href="#prilohy" aria-label="Permalink to &quot;Přílohy&quot;">​</a></h2><p>Přílohy úkolu najdete na druhé záložce. Fotky a soubory se otevírají ve vestavěném prohlížeči přímo v aplikaci.</p><p>Novou přílohu přidáte ikonami v dolní liště úkolu – fotoaparát, galerie, nebo kancelářská sponka pro video a další soubory. Fotek i souborů můžete vybrat několik najednou, i na iPhonu.</p><figure class="shot" style="--w:260px;"><img src="'+s+'" alt="Nabídka přílohy s volbami Upravit, Sdílet a Smazat" loading="lazy"></figure><p>Nabídku přílohy otevřete ikonou tří teček v jejím rohu:</p><ul><li><strong>Sdílet</strong> – pošle přílohu jinou aplikací v telefonu. Volba je dostupná všem.</li><li><strong>Smazat</strong> – jen pro autora přílohy.</li><li><strong>Upravit</strong> – jen pro autora a jen u obrázků. Otevře editor fotky – viz <a href="/buildary-help-preview/tickets/m_task_new#upravit-fotku">Nový úkol v mobilu</a>.</li></ul><h2 id="bez-signalu" tabindex="-1">Bez signálu <a class="header-anchor" href="#bez-signalu" aria-label="Permalink to &quot;Bez signálu&quot;">​</a></h2><p>Úkoly, které jste už otevřeli, můžete upravovat i bez připojení a přidávat k nim vyjádření. Změny se odešlou na server při synchronizaci – viz <a href="/buildary-help-preview/diary/m_offline">Práce bez signálu</a>.</p>',38)])])}const S=k(d,[["render",m]]);export{w as __pageData,S as default};
